const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Bhadla Solar Park location (approximate center and buffer)
  const bhadlaCenter = ee.Geometry.Point([71.9, 27.5]);
  const studyArea = bhadlaCenter.buffer(8000); // 8km radius to cover the park

  // 2. Time period
  const startDate = '2022-01-01';
  const endDate = '2022-01-31';

  // 3. Load Sentinel-2 data
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(studyArea)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const collectionSize = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collectionSize}`);

  if (collectionSize === 0) {
    // Try Landsat 8 as fallback
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(studyArea)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const landsatSize = collection.size().getInfo();
    console.log(`Fallback Landsat 8 images: ${landsatSize}`);

    if (landsatSize === 0) {
      console.log('No imagery available for January 2022');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Create composite and identify solar panels
  const composite = collection.median();

  // Calculate NDVI for Sentinel-2
  const ndvi = composite.normalizedDifference(['B8', 'B4']).rename('NDVI');

  // Solar panels typically have:
  // - Very low NDVI (< 0.1, often negative)
  // - High reflectance in visible bands
  const solarMask = ndvi.lt(0.15);

  // 5. Calculate area
  const pixelArea = solarMask.multiply(ee.Image.pixelArea());

  const stats = pixelArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: studyArea,
    scale: 100,
    maxPixels: 1e9
  });

  const totalAreaM2 = stats.get('NDVI').getInfo();

  if (totalAreaM2 === null || totalAreaM2 === undefined) {
    console.log('Calculation failed - no valid result');
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Count valid pixels
  const pixelCount = solarMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: studyArea,
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Valid pixels analyzed: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Convert to hectares and compare
  const areaHectares = totalAreaM2 / 10000;
  const threshold = 7000;

  console.log(`Total low-NDVI area (solar panels): ${areaHectares.toFixed(2)} hectares`);
  console.log(`Threshold: ${threshold} hectares`);

  if (areaHectares > threshold) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
